import {occupations,occupationById} from './occupation-data.js';
import {expandedOccupations} from './expanded-occupation-data.js';
import {occupationEssentials} from './occupation-essentials.js';
import {scoreOnetInterest,profileCorrelation,riasecNames,riasecOrder} from './onet-assessment.js';
import {professionQuestions} from './profession-questions.js';
import {taskEvidenceDomain} from './career-check-questions.js';
import {coreWorkQuestions} from './core-work.js';
import {expandedQuestionBank} from './expanded-question-bank.js';
import {careerFamilies} from './guide-state.js';
import {explorerMembership} from './explorer-053-membership-data.js';
import {explorerQuestions} from './explorer-053-questions.js';
export const explorerVersion='0.53.0';
export const explorerCatalog=[...occupations,...expandedOccupations];
const familyIds=new Set(careerFamilies.map(f=>f.id));
const eligible=a=>!!a&&!a.reviewHold&&(a.source!=='profile-inferred'||(['high','medium'].includes(a.confidence)&&!!a.evidence?.trim()));
const yes=a=>eligible(a)&&a.response==='yes';
const descriptors=new Map(explorerCatalog.map(o=>{const e=occupationEssentials[o.soc],vector=o.vector|| (e?.interests?.length===6?riasecOrder.map(k=>e.interests.find(x=>x.name===riasecNames[k])?.value):null);return[o.id,{o,vector,fields:explorerMembership[o.id]?.fields||[],tasks:Object.entries(professionQuestions).flatMap(([field,qs])=>qs.filter(q=>q.kind!=='route'&&q.options.some(x=>x.careerIds.includes(o.id))).map(q=>({field,q}))),core:coreWorkQuestions(o.id),expanded:expandedQuestionBank[o.id]}];}));
export const explorerDegree=o=>['college','graduate'].includes(o.educationGroup)||/bachelor|master|doctor|professional|graduate/i.test(o.finance?.credentialLevel||'')||o.finance?.routeType==='college';
export const explorerEducation=o=>o.educationGroup==='graduate'||/master|doctor|professional|graduate/i.test(o.finance?.credentialLevel||'')?'Graduate / professional':explorerDegree(o)?'College degree':o.preparation?.typicalEducation?.[0]||'Training route varies';
export function explorerFieldQuestions(field){if(!familyIds.has(field))return [];const qs=(professionQuestions[field]||[]).filter(q=>q.kind!=='route'),selected=[],domains=new Set();for(const q of qs){const d=taskEvidenceDomain(q);if(!domains.has(d)){selected.push(q);domains.add(d);}}for(const q of qs)if(!selected.includes(q)&&selected.length<12)selected.push(q);return selected.slice(0,12);}
export function explorerCareerQuestions(id){const d=descriptors.get(id);if(!d)return [];if(d.expanded?.topEligible)return d.expanded.questions.map(q=>({...q,kind:'specific'}));const tasks=[];for(const{q,field}of d.tasks){if(!tasks.some(x=>taskEvidenceDomain(x)===taskEvidenceDomain(q)))tasks.push({...q,field});if(tasks.length===3)break;}return [...tasks,...d.core.map(q=>({...q,kind:'specific'}))];}
export function explorerAnswer(s,kind,scope,q){const fresh=s.explorer053?.[kind==='field'?'fieldAnswers':'professionAnswers']?.[scope]?.[q.id];if(fresh)return fresh;const j=s.profileJourney||{};if(q.kind==='specific'||q.kind==='core-work')return j.expandedInterests?.[q.id]||j.coreWork?.[q.id]||null;const old=j.depth?.[q.field||scope]?.[q.id];if(!Array.isArray(old))return null;return{selected:old,source:'student',confidence:'high',legacy:true,feedback:j.careerQuestionFeedback?.[q.id]};}
function taskAnswer(s,id,field,q){return s.explorer053?.professionAnswers?.[id]?.[q.id]||s.explorer053?.fieldAnswers?.[field]?.[q.id]||explorerAnswer(s,'field',field,q);}
function specificAnswer(s,id,q){return s.explorer053?.professionAnswers?.[id]?.[q.id]||s.profileJourney?.expandedInterests?.[q.id]||s.profileJourney?.coreWork?.[q.id]||null;}
export function explorerEvidence(s,id){const d=descriptors.get(id);if(!d)return null;const evidence=[],contrary=[],asked=new Set(),taskDomains=new Set();
 for(const{field,q}of d.tasks){const a=taskAnswer(s,id,field,q);if(!a)continue;asked.add(q.id);const options=q.options.filter(x=>x.careerIds.includes(id)&&a.selected?.includes(x.id));if(eligible(a)&&options.length&&!a.feedback){const domain=taskEvidenceDomain(q);taskDomains.add(domain);evidence.push({questionId:q.id,prompt:q.prompt,domain,text:options.map(x=>x.text).join('; '),source:a.source||'student',confidence:a.confidence||'high',evidence:a.evidence||'',kind:'task'});}}
 const checks=d.expanded?.topEligible?d.expanded.questions:d.core,specificDomains=new Set();for(const q of checks){const a=specificAnswer(s,id,q);if(!a)continue;asked.add(q.id);if(a.response==='no'&&eligible(a))contrary.push({questionId:q.id,prompt:q.prompt,source:a.source,evidence:a.evidence||''});if(yes(a)){const domain=q.domain||q.id;specificDomains.add(domain);evidence.push({questionId:q.id,prompt:q.prompt,domain,text:q.prompt,source:a.source,confidence:a.confidence,evidence:a.evidence||'',kind:'specific'});}}
 const distinctExpanded=d.expanded?.topEligible&&checks.length===3&&specificDomains.size===3;
 const distinctGuided=!d.expanded&&checks.length===2&&specificDomains.size===2&&taskDomains.size>=2;
 const supported=!!(distinctExpanded||distinctGuided)&&!contrary.length;
 return{supported,contrary,evidence,asked:asked.size,taskDomains:[...taskDomains],specificDomains:[...specificDomains],inferred:evidence.some(e=>e.source==='profile-inferred'),missing:checks.filter(q=>!yes(specificAnswer(s,id,q))).map(q=>({id:q.id,prompt:q.prompt})),requirement:d.expanded?'Subject, method and distinctive responsibility need independent support.':'Two distinct task contexts and both defining interests need support.',taskDomainCount:taskDomains.size};}
const cache=new WeakMap();
export function explorerResults(s,{scope='all',education='all',query='',sort='evidence',saved=false}={}){const signature=JSON.stringify([s.profileJourney?.officialInterest,s.profileJourney?.depth,s.profileJourney?.coreWork,s.profileJourney?.expandedInterests,s.profileJourney?.careerQuestionFeedback,s.explorer053]);let base=cache.get(s);if(!base||base.signature!==signature){const profile=scoreOnetInterest(s),valid=profile.complete&&!profile.flat&&!profile.nearFlat;
 const rows=explorerCatalog.map(o=>{const d=descriptors.get(o.id),specific=explorerEvidence(s,o.id),r=valid&&d.vector?.every(Number.isFinite)?profileCorrelation(profile.raw,d.vector):null;return{id:o.id,o,fields:d.fields,r,specific,degree:explorerDegree(o),band:specific.supported?'Specific interests supported':specific.contrary.length?'Mixed specific interests':r!==null&&r>=.608?'Broad profile connection':specific.evidence.length?'Some specific interest evidence':'Open to explore'};});base={signature,profile,rows};cache.set(s,base);}
 const validScope=scope==='all'||familyIds.has(scope);let rows=validScope?base.rows.filter(r=>scope==='all'||r.fields.includes(scope)):[];if(education==='degree')rows=rows.filter(r=>r.degree);if(saved)rows=rows.filter(r=>s.careerLibrary?.saved?.includes(r.id));const q=String(query).trim().toLowerCase();if(q)rows=rows.filter(r=>[r.o.title,r.o.soc,r.o.summary,...(r.o.aliases||[])].join(' ').toLowerCase().includes(q));
 const rValue=r=>r.r??-2;
 rows=[...rows].sort((a,b)=>sort==='correlation'?rValue(b)-rValue(a)||a.id.localeCompare(b.id):Number(b.specific.supported)-Number(a.specific.supported)||Number(a.specific.contrary.length>0)-Number(b.specific.contrary.length>0)||Number(b.specific.specificDomains.length>0||b.specific.taskDomainCount>=2)-Number(a.specific.specificDomains.length>0||a.specific.taskDomainCount>=2)||rValue(b)-rValue(a)||b.specific.specificDomains.length-a.specific.specificDomains.length||b.specific.taskDomainCount-a.specific.taskDomainCount||a.id.localeCompare(b.id));return{version:explorerVersion,profile:base.profile,rows,total:rows.length,scope:validScope?scope:'invalid'};}
export function explorerFieldSummary(s){const rows=explorerResults(s).rows;return careerFamilies.map(f=>({id:f.id,title:f.title,careers:rows.filter(r=>r.fields.includes(f.id)).slice(0,3),count:rows.filter(r=>r.fields.includes(f.id)).length}));}
export function resolveExplorerRoute(s,r){const[path]=r.split('?');if(path==='plan')return s.guide?.primaryCareer?'plan':'journey/explore';if(/^journey\/profession\/[a-z0-9-]+$/.test(path))return r;if(['guide/paths','guide/specialty','guide/work-fit','guide/careers','guide/assessment-results'].includes(path))return 'journey/explore';if(path==='guide/assessment')return resolveExplorerRoute(s,'journey/profile');if(/^journey\/(explore|interest-intro|interest\/\d+|refine\/\d+|strengths\/\d+|field-survey\/[a-z-]+\/\d+|clarify\/[a-z0-9-]+\/\d+)(?:$)/.test(path))return r;
 if(['journey/pathways','journey/discover','journey/expanded-matches'].includes(path))return'journey/explore';
 if(path==='journey/professions')return'journey/explore'+(s.profileJourney?.family?'?scope='+s.profileJourney.family:'');
 if(path==='journey/deeper')return s.profileJourney?.family?'journey/field-survey/'+s.profileJourney.family+'/0':'journey/explore';
 if(path==='journey/profile-intro')return 'journey/interest-intro';if(['journey/profile-followups','journey/followup-intro','journey/profile-priorities','journey/profile-working-life'].includes(path))return scoreOnetInterest(s).complete?'journey/explore':'journey/interest-intro';if(path==='journey/profile-experience')return 'journey/strengths/0';if(path==='journey/profession-intro')return 'journey/explore'+(s.profileJourney?.family?'?scope='+s.profileJourney.family:'');if(path==='journey/profile'){const a=s.profileJourney?.officialInterest?.answers||{},i=Array.from({length:60},(_,i)=>i).find(i=>!Number.isInteger(a['onet-sf-'+String(i+1).padStart(2,'0')]));return i===undefined?'journey/explore':'journey/interest/'+i;}return null;}
